import { QueryClient } from '@tanstack/react-query';

import { ContentLayout } from '@/components/layouts';
import { GetUsersParams, getUsersQueryOptions } from '@/features/users/api/get-users';
import { UsersList } from '@/features/users/components/users-list';
import { Authorization, ROLES } from '@/lib/authorization';

export const clientLoader =
  (queryClient: QueryClient) =>
  async ({}: {
    request: Request;
  }): Promise<{ params: GetUsersParams | undefined }> => {
    const url = new URL(request.url);
    const role = url.searchParams.get('role') as GetUsersParams['role'] | null;
    const search = url.searchParams.get('search') || undefined;

    const params: GetUsersParams | undefined =
      role || search
        ? {
            ...(role ? { role } : {}),
            ...(search ? { search } : {}),
          }
        : undefined;

    const query = params ? getUsersQueryOptions(params) : getUsersQueryOptions();

    return {
      params: params ?? undefined,
      data:
        queryClient.getQueryData(query.queryKey) ??
        (await queryClient.fetchQuery(query)),
    };
  };

const UsersRoute = () => {
  return (
    <ContentLayout title=\"Users\">
      <Authorization
        forbiddenFallback={<div>Only admin can view this.</div>}
        allowedRoles={[ROLES.ADMIN]}
      >
        <UsersList />
      </Authorization>
    </ContentLayout>
  );
};

export default UsersRoute;
